def count_vowels(s, memo=None):
    if memo is None:
        memo = {}
    s = s.upper()
    if s in memo:
        return memo[s]
    if len(s) == 0:
        result = 0
    elif s[0] in 'AEIOU':
        result = 1
    else:
        result = 0
    if len(s) > 1:
        if s[1] in 'AEIOU':
            result += count_vowels(s[1:], memo)
        result += count_vowels(s[2:], memo)
    memo[s] = result
    return result
```

